public class SumNumericCharacters {
    // Optimized Approach: O(N) time, O(1) space
    public static int sumNumericOptimized(String s) {
        if (s == null || s.isEmpty()) return 0;

        int totalSum = 0;
        int currentNum = 0;

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            if (Character.isDigit(ch)) {
                // Multiply currentNum by 10 and add the integer value of character digit
                currentNum = currentNum * 10 + (ch - '0');
            } else {
                // Flush current sequence of digits to total sum
                totalSum += currentNum;
                currentNum = 0;
            }
        }
        // Add any remaining number accumulated at the end of string
        totalSum += currentNum;

        return totalSum;
    }

    public static void main(String[] args) {
        System.out.println(sumNumericOptimized("10a20b30"));  // 60
        System.out.println(sumNumericOptimized("abc123xyz")); // 123
        System.out.println(sumNumericOptimized("00abc12ghj"));// 12
        System.out.println(sumNumericOptimized("5 5 5"));     // 15
    }
}

