    public static Map<String, Integer> countFrequency(String[] arr, boolean ignoreCase) {
        Map<String, Integer> freqMap = new LinkedHashMap<>();

        for (String str : arr) {
            if (str == null) continue;
            String key = ignoreCase ? str.toLowerCase() : str;
            freqMap.put(key, freqMap.getOrDefault(key, 0) + 1);
        }
        return freqMap;
    }

    public static void main(String[] args) {
        String[] input1 = {"apple", "banana", "apple"};
        System.out.println(countFrequency(input1, false)); // {"apple": 2, "banana": 1}

        String[] input6 = {"Apple", "apple", "APPLE"};
        System.out.println(countFrequency(input6, true));  // {"apple": 3}
    }
